const { accessSync } = await import('node:fs');
const pdfPath = process.env.PDF_PATH;
if (!pdfPath) { throw new Error('Missing required input PDF_PATH'); }
try { accessSync(pdfPath); } catch (e) { throw new Error('PDF file not found at ' + pdfPath); }
globalThis.pdfPath = pdfPath;

const { readFileSync } = await import('node:fs');
const mod = await import('pdf-parse');
const PDFParse = mod.PDFParse || mod.default?.PDFParse || mod.default;
if (!PDFParse) { throw new Error('PDFParse class not found in pdf-parse package'); }
const buffer = readFileSync(globalThis.pdfPath);
const parser = new PDFParse({ data: buffer });
const result = await parser.getText();
await parser.destroy();
globalThis.textResult = result.text;
